"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["76787"],{6087(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_do_fada.teto_invalido","status":422,"titulo":"O teto do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso (FADA), quando informado, deve ser maior que zero"},"descricao":{"codigo":"uniplus.selecao.configuracao_do_fada.teto_invalido","requisitos":[],"oQueAconteceu":["O `teto` informado na declara\xe7\xe3o do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso \xe9 zero ou\\nnegativo. O teto \xe9 opcional: quando o processo n\xe3o o declara, n\xe3o h\xe1 teto. Informado, s\xf3 vale\\num n\xfamero maior que zero.","A recusa vem no campo `teto` e acumula, na mesma resposta, com as demais viola\xe7\xf5es dos\\nvalores do fator, em\\n[`fator_invalido`](/erros/uniplus.selecao.configuracao_do_fada.fator_invalido) e\\n[`fato_elegibilidade_invalido`](/erros/uniplus.selecao.configuracao_do_fada.fato_elegibilidade_invalido).\\nEla vem depois da confer\xeancia da regra e da base legal; se alguma delas falhar, os valores\\nnem chegam a ser conferidos.","Esta mesma confer\xeancia tamb\xe9m roda quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o\\npublicada, na retifica\xe7\xe3o em ato \xfanico. Nesse caso a recusa sai como uma viola\xe7\xe3o \xfanica (sem a lista `errors[]`) e se\\nrefere \xe0 vers\xe3o congelada, n\xe3o ao pedido enviado."],"comoResolver":["Na declara\xe7\xe3o, omita o `teto` se o edital n\xe3o fixa teto, ou informe um valor maior que zero.","Se o erro apareceu na retifica\xe7\xe3o em ato \xfanico, o pedido enviado agora n\xe3o \xe9 a causa: o sistema recusou a\\nconfigura\xe7\xe3o congelada da vers\xe3o publicada, e regravar a configura\xe7\xe3o do processo n\xe3o a\\ncorrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Declara\xe7\xe3o do Fator de Atenua\xe7\xe3o das Desigualdades de Acesso do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao do fada"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);